server <- function(input, output, session) {
  # State
  active <- reactiveVal(list())
  counter <- reactiveVal(0)
  restored <- reactiveVal(FALSE)
  restoring <- reactiveVal(FALSE)
  
  
  # # Save state
  # save_state <- function() {
  #   # print("save state")
  #   state <- lapply(active(), function(x) x$returns$get_state())
  #   runjs(sprintf(
  #     "localStorage.setItem('middara_calculator_v0.1.0', '%s');",
  #     toJSON(state, auto_unbox = TRUE)
  #   ))
  # }
  
  save_state <- function() {
    # print("save state")
    # browser()
    module_states <- lapply(active(), function(x) x$returns$get_state())
    
    global_state <- list(
      game_ver = input$game_ver %||% "1_2"
    )
    
    full_state <- list(
      modules = module_states,
      global = global_state
    )
    
    runjs(sprintf(
      "localStorage.setItem('middara_calculator_v0.1.0', '%s');",
      toJSON(full_state, auto_unbox = TRUE)
    ))
  }
  
  
  # Add a tab
  add_tab <- function(id, initial = NULL) {
    insertTab(
      inputId = "navbar",
      tabPanel(
        title = uiOutput(NS(id, "title_ui")),
        value = id,
        tabUI(id)
      ),
      position = "after"
    )
    
    mod <- tabServer(id, save_state, restoring, reactive(input$game_ver))
    active(c(active(), list(list(id = id, returns = mod))))
    
    if (!is.null(initial)) {
      session$onFlushed(function() {
        updateTextInput(session, NS(id, "tab_name"), value = initial$tab_name)
        
        updatePickerInput(session, NS(id, "die_1"), selected = initial$die_1 %||% "purple")
        updatePickerInput(session, NS(id, "die_2"), selected = initial$die_2 %||% "purple")
        
        updateRadioGroupButtons(session, NS(id, "symbols_1_type"), selected = initial$symbols_1_type %||% "1")
        
        updatePickerInput(session, NS(id, "symbols_1_effect_raw"), selected = initial$symbols_1_effect_raw %||% "dmg")
        updateNumericInput(session, NS(id, "symbols_1_modifier"), value = initial$symbols_1_modifier %||% 0)
        updatePrettyToggle(session, NS(id, "symbols_1_damage_type"), value = initial$symbols_1_damage_type %||% FALSE)
        
        updatePickerInput(session, NS(id, "burst_effect_raw"), selected = initial$burst_effect_raw %||% "dmg")
        updateNumericInput(session, NS(id, "burst_modifier"), value = initial$burst_modifier %||% 0)
        updatePrettyToggle(session, NS(id, "burst_damage_type"), value = initial$burst_damage_type %||% FALSE)
        
        updateCheckboxGroupButtons(session,NS(id, "is_symbols_2"), selected = initial$is_symbols_2)
        updateRadioGroupButtons(session, NS(id, "symbols_2_type"), selected = initial$symbols_2_type %||% "1")
        updatePickerInput(session, NS(id, "symbols_2_effect_raw"), selected = initial$symbols_2_effect_raw %||% "dmg")
        updateNumericInput(session, NS(id, "symbols_2_modifier"), value = initial$symbols_2_modifier %||% 0)
        updatePrettyToggle(session, NS(id, "symbols_2_damage_type"), value = initial$symbols_2_damage_type %||% FALSE)
        
        
        
        updateNumericInput(session, NS(id, "add_armor_pierce"), value = initial$add_armor_pierce %||% 0)
        
        updateNumericInput(session, NS(id, "add_attack_roll"), value = initial$add_attack_roll %||% 0)
        updateNumericInput(session, NS(id, "add_phys_damage"), value = initial$add_phys_damage %||% 0)
        updateNumericInput(session, NS(id, "add_mag_damage"), value = initial$add_mag_damage %||% 0)
        
        updateNumericInput(session, NS(id, "flank_attack_roll"), value = initial$flank_attack_roll %||% 1)
        updateNumericInput(session, NS(id, "flank_damage"), value = initial$flank_damage %||% 0)
        
      }, once = TRUE)
    }
    counter(counter() + 1)
    
    # if (save_after){
    #   save_state()
    # }
  }
  
  # Restore from localStorage
  observeEvent(input$restore_state, {
    
    if (restored()) return()
    restored(TRUE)
    restoring(TRUE)
    state <- fromJSON(input$restore_state, simplifyVector = FALSE)
    if (length(state) == 0) {
      restoring(FALSE)
      return()
    }
    # browser()
    if (!is.null(state$global)) {
      updatePickerInput(session, "game_ver", selected = state$global$game_ver %||% "1_2")
    }
    
    # Clear any default tabs (if any)
    active(list())
    # Set counter to max id
    
    if (length(state$modules) > 0) {
      max_id <- max(sapply(state$modules, function(x) as.numeric(gsub("tab_", "", x$id))), 0)
      counter(max_id)
      for (s in state$modules) add_tab(s$id %||% paste0("tab_", counter() + 1), s)
      
    }
    restoring(FALSE)
    # save_state()
  }, ignoreNULL = TRUE)
  
  
  # Add tab 
  observeEvent(
    input$add_new_tab, {
      if (length(active()) >= 20) {
        showNotification("Maximum number of tabs reached.", type = "warning")
        return()
      }
      add_tab(paste0("tab_", counter() + 1))
    }
  )
  
  
  # Remove all tabs
  observeEvent(
    input$close_all_tabs,
    {
      ask_confirmation(
        inputId = "close_all_tabs_confirm",
        title = "Close all tabs?",
        text = HTML("<b>All</b> tabs (except for this one) will be closed. <br/>Continue?"),
        btn_labels = c("Cancel", "Ok"),
        closeOnClickOutside = TRUE,
        html = TRUE
      )
    }
  )
  
  observeEvent(
    input$close_all_tabs_confirm,
    {
      if (isTRUE(input$close_all_tabs_confirm)) {
        mods <- active()
        for (i in seq_along(mods)) {
          removeTab("navbar", mods[[i]]$id)
        }
        active(list())
        
        save_state()
      }
    }
  )
  
  observeEvent(
    input$game_ver,
    {
      save_state()
    },
    ignoreInit = TRUE
  )
  
  
  # Remove tab when close triggered
  observe({
    mods <- active()
    for (i in seq_along(mods)) {
      if (mods[[i]]$returns$remove()) {
        removeTab("navbar", mods[[i]]$id)
        active(mods[-i])
        save_state()
        break
      }
    }
  })
}

