tabServer <- function(id, notify_parent, restoring, game_ver) {
  moduleServer(id, function(input, output, session) {
    # Live tab title
    output$title_ui <- renderText({
      if (trimws(input$tab_name) == "") {
        "Untitled"
      } else {
        trimws(input$tab_name)
      }
    })
    
    output$die_1_result <- renderUI({
      req(input$die_1)
      
      div(
        class = "btn-group-justified",
        radioGroupButtons(
          inputId = session$ns("die_1_result_s"),
          label = NULL,
          choiceNames = lapply(
            1:6,
            function(i) tags$img(
              src = paste0("die_faces/", input$die_1, "_", i, ".png"),
              class = "dice-face"
            )
          ),
          choiceValues = 1:6,
          justified = TRUE
        )
      )
    })
    
    output$die_2_result <- renderUI({
      req(input$die_2)
      div(
        radioGroupButtons(
          inputId = session$ns("die_2_result_s"),
          label = NULL,
          choiceNames = lapply(
            1:6,
            function(i) tags$img(
              src = paste0("die_faces/", input$die_2, "_", i, ".png"),
              class = "dice-face"
            )
          ),
          choiceValues = 1:6,
          justified = TRUE
        )
      )
    })
    
    
    
    roll_result_tab <- reactive({
      req(input$symbols_1_type)
      # browser()
      
      curr_die_1 <- dice_all[id %in% input$die_1 & side %in% input$die_1_result_s]
      curr_die_2 <- dice_all[id %in% input$die_2 & side %in% input$die_2_result_s]
      
      curr_roll <- rbind(curr_die_1, curr_die_2)
      curr_roll <- curr_roll[,.(
        atk_val = sum(value), 
        shields = sum(shields), 
        books = sum(books), 
        bursts = sum(bursts),
        
        dmg_phys = 0,
        dmg_mag = 0,
        
        move = 0,
        armor_pierce = 0,
        heal = 0,
        special_1 = 0,
        special_2 = 0,
        special_burst = 0
      )]
      
      
      # Flank bonus
      if ("flank" %in% input$add_modifiers) {
        curr_roll <- curr_roll[, atk_val := atk_val + input$flank_attack_roll]
        curr_roll <- curr_roll[, dmg_phys := dmg_phys + input$flank_damage]
      }
      
      # Other bonuses
      curr_roll <- curr_roll[, armor_pierce := armor_pierce + input$add_armor_pierce]
      curr_roll <- curr_roll[, atk_val := atk_val + input$add_attack_roll]
      curr_roll <- curr_roll[, dmg_phys := dmg_phys + input$add_phys_damage]
      curr_roll <- curr_roll[, dmg_mag := dmg_mag + input$add_mag_damage]
      
      
      
      # Calculating symbols
      if ("courage" %in% input$add_modifiers) {
        curr_roll <- curr_roll[, shields := shields + 1]
        curr_roll <- curr_roll[, books := books + 1]
        # browser()
        # if (input$game_ver == "1_1") {
        if (game_ver() == "1_1") {
          curr_roll <- curr_roll[, bursts := bursts + 1]
        }
      }
      if ("empower" %in% input$add_modifiers) {
        empower_roll <- empower_ref[side == input$empower_result]
        
        curr_roll <- curr_roll[, shields := shields + empower_roll$shields]
        curr_roll <- curr_roll[, books := books + empower_roll$books]
      }
      
      
      curr_type <- modifiers_ref$id[as.numeric(input$symbols_1_type)]
      curr_mod <- input$symbols_1_modifier
      if (curr_type == "shield_1") {
        curr_roll <- curr_roll[, mod_1 := shields * curr_mod]
        curr_roll <- curr_roll[, shields := 0]
      } else if (curr_type == "shield_2") {
        curr_roll <- curr_roll[, mod_1 := shields %/% 2 * curr_mod]
        curr_roll <- curr_roll[, shields := shields %% 2]
      } else if (curr_type == "book_1") {
        curr_roll <- curr_roll[, mod_1 := books * curr_mod]
        curr_roll <- curr_roll[, books := 0]
      } else if (curr_type == "book_2") {
        curr_roll <- curr_roll[, mod_1 := books %/% 2 * curr_mod]
        curr_roll <- curr_roll[, books := books %% 2]
      } else if (curr_type == "shield_book") {
        curr_roll <- curr_roll[, mod_1 := pmin(books, shields)]
        curr_roll <- curr_roll[, books := books - mod_1]
        curr_roll <- curr_roll[, shields := shields - mod_1]
        curr_roll <- curr_roll[, mod_1 := mod_1 * curr_mod]
      }
      
      # Adding symbol bonuses
      curr_effect <- input$symbols_1_effect_raw
      if (curr_effect == "dmg") {
        curr_effect <- paste0(curr_effect, "_", ifelse(input$symbols_1_damage_type, "mag", "phys"))
      }
      curr_roll <- curr_roll[, (curr_effect) := get(curr_effect) + mod_1]
      
      
      # Repeat if an additional set of symbols is specified
      if ("symbols_2" %in% input$is_symbols_2) {
        curr_type <- modifiers_ref$id[as.numeric(input$symbols_2_type)]
        curr_mod <- input$symbols_2_modifier
        if (curr_type == "shield_1") {
          curr_roll <- curr_roll[, mod_2 := shields * curr_mod]
          curr_roll <- curr_roll[, shields := 0]
        } else if (curr_type == "shield_2") {
          curr_roll <- curr_roll[, mod_2 := shields %/% 2 * curr_mod]
          curr_roll <- curr_roll[, shields := shields %% 2]
        } else if (curr_type == "book_1") {
          curr_roll <- curr_roll[, mod_2 := books * curr_mod]
          curr_roll <- curr_roll[, books := 0]
        } else if (curr_type == "book_2") {
          curr_roll <- curr_roll[, mod_2 := books %/% 2 * curr_mod]
          curr_roll <- curr_roll[, books := books %% 2]
        } else if (curr_type == "shield_book") {
          curr_roll <- curr_roll[, mod_2 := pmin(books, shields)]
          curr_roll <- curr_roll[, books := books - mod_2]
          curr_roll <- curr_roll[, shields := shields - mod_2]
          curr_roll <- curr_roll[, mod_2 := mod_2 * curr_mod]
        }
        
        # Adding symbol bonuses
        curr_effect <- input$symbols_2_effect_raw
        if (curr_effect == "dmg") {
          curr_effect <- paste0(curr_effect, "_", ifelse(input$symbols_2_damage_type, "mag", "phys"))
        }
        curr_roll <- curr_roll[, (curr_effect) := get(curr_effect) + mod_2]
      }
      
      
      curr_effect <- input$burst_effect_raw
      if (curr_effect == "dmg") {
        curr_effect <- paste0(curr_effect, "_", ifelse(input$burst_damage_type, "mag", "phys"))
      }
      curr_roll <- curr_roll[, (curr_effect) := get(curr_effect) + bursts * input$burst_modifier]
      
      
      curr_roll
    })
    
    output$roll_result <- renderText({
      req(roll_result_tab())
      
      # browser()
      result <- roll_result_tab() |> copy()
      
      result <- result[, dmg_phys := dmg_phys + atk_val]
      result <- result[, dmg_total := dmg_phys + dmg_mag]
      result <- melt(result, measure.vars = names(result))
      result <- result[value != 0]
      
      result <- merge(result, result_desctiption_ref, by = c("variable"))
      result <- result[order(sort_val)]
      result <- result[variable != "dmg_mag", description := paste0(description, "<b>", value, "</b>")]
      result <- result[variable == "dmg_mag", description := paste0(
        description, 
        "<b>", result[variable == "dmg_total"]$value - value, "</b> physical + ",
        "<b>", value, "</b> magical)"
      )]
      
      result_text <- paste(result$description, collapse = "")
      
      HTML(result_text)
    })
    
    
    
    
    
    
    
    
    # Notify parent on any change
    combined_inputs <- reactive({
      list(
        input$tab_name,
        
        input$die_1,
        input$die_2,
        
        input$symbols_1_type,
        
        input$symbols_1_effect_raw,
        input$symbols_1_modifier,
        input$symbols_1_damage_type,
        
        input$burst_effect_raw,
        input$burst_modifier,
        input$burst_damage_type,
        
        input$symbols_2_type,
        input$is_symbols_2,
        input$symbols_2_effect_raw,
        input$symbols_2_modifier,
        input$symbols_2_damage_type,
        
        input$add_armor_pierce,
        
        input$add_attack_roll,
        input$add_phys_damage,
        input$add_mag_damage,
        
        input$flank_attack_roll,
        input$flank_damage
        
      )
    })
    debounced_inputs <- debounce(combined_inputs, millis = 5000)
    
    observeEvent(debounced_inputs(), {
      # browser()
      if (!restoring()){
        notify_parent()
      }
    }, ignoreInit = TRUE)
    
    
    
    # Close signal
    remove_signal <- reactiveVal(FALSE)
    # observeEvent(input$close_tab, remove_signal(TRUE))
    
    observeEvent(
      input$close_tab,
      {
        ask_confirmation(
          inputId = "close_tab_confirm",
          title = "Close the current tab?",
          text = "Closed tabs can't be restored. Continue?",
          btn_labels = c("I just pushed it because it is red", "Sure"),
          closeOnClickOutside = TRUE
        )
      }
    )
    
    observeEvent(
      input$close_tab_confirm,
      {
        if (isTRUE(input$close_tab_confirm)) {
          remove_signal(TRUE)
        }
      }
    )
    
    
    # Return interface
    return(list(
      remove = reactive({ remove_signal() }),
      get_state = function() {
        state <- list(
          id = id,
          
          tab_name = input$tab_name,
          die_1 = input$die_1,
          die_2 = input$die_2,
          
          symbols_1_type = input$symbols_1_type,
          symbols_1_effect_raw = input$symbols_1_effect_raw,
          symbols_1_modifier = input$symbols_1_modifier,
          symbols_1_damage_type = input$symbols_1_damage_type,
          
          burst_effect_raw = input$burst_effect_raw,
          burst_modifier = input$burst_modifier,
          burst_damage_type = input$burst_damage_type,
          
          symbols_2_type = input$symbols_2_type,
          is_symbols_2 = input$is_symbols_2,
          symbols_2_effect_raw = input$symbols_2_effect_raw,
          symbols_2_modifier = input$symbols_2_modifier,
          symbols_2_damage_type = input$symbols_2_damage_type,
          
          
          add_armor_pierce = input$add_armor_pierce,
          
          add_attack_roll = input$add_attack_roll,
          add_phys_damage = input$add_phys_damage,
          add_mag_damage = input$add_mag_damage,
          
          flank_attack_roll = input$flank_attack_roll,
          flank_damage = input$flank_damage
          
        )
        # print("get state called")
        # print(str(state))
        # browser()
        
        return(state)
      }
    ))
  })
}
